def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    # Find the two horizontal bars (non-background runs).
    bars = []
    for r, row in enumerate(grid):
        c = 0
        while c < w:
            if row[c] == bg:
                c += 1
                continue
            color, a = row[c], c
            while c < w and row[c] == color:
                c += 1
            if c-a >= 2:
                bars.append((r, a, c-1, color))
    bars.sort()
    top, bottom = bars[0], bars[-1]
    bc = top[3]
    marks = [(r,c) for r in range(h) for c in range(w)
             if grid[r][c] != bg and grid[r][c] != bc]
    mc = grid[marks[0][0]][marks[0][1]]
    n = len(marks)
    out = [row[:] for row in grid]
    minmark, maxmark = min(c for r,c in marks), max(c for r,c in marks)
    # Each bar extends inward in a strip as wide as the number of markers,
    # using the end nearest the marker pattern.
    def marker_near_cols(bar):
        r,a,b,color = bar
        target = sum(c for rr,c in marks)/len(marks)
        if abs(a-target) < abs(b-target):
            return range(a, min(a+n, b+1))
        return range(max(a,b-n+1), b+1)
    for c in marker_near_cols(top):
        for r in range(top[0]+1, bottom[0]):
            out[r][c] = mc
    # Continue the marker pattern's filled side down to the lower bar.
    lowcols = range(minmark, minmark+n)
    # use the marker-adjacent end of the bottom bar
    bcandidates = list(marker_near_cols(bottom))
    lowcols = bcandidates
    start = max(r for r,c in marks)
    for r in range(start, bottom[0]):
        for c in lowcols:
            out[r][c] = mc
    for r,c in marks:
        out[r][c] = 4
    return out

