def transform(grid):
    from collections import Counter
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    runs=[]
    for r,row in enumerate(grid):
        c=0
        while c<w:
            if row[c]==bg:
                c+=1; continue
            color,a=row[c],c
            while c<w and row[c]==color: c+=1
            if c-a>=2: runs.append((r,a,c-1,color))
    runs.sort()
    top,bottom=runs[0],runs[-1]
    markers=[(r,c) for r in range(h) for c in range(w) if grid[r][c]!=bg and grid[r][c]!=top[3]]
    fill=grid[markers[0][0]][markers[0][1]]
    out=[row[:] for row in grid]
    n=len(markers)
    def inward(bar):
        _,a,b,_=bar
        if (a+b)/2 < (w-1)/2:
            return range(max(a,b-n+1),b+1)
        return range(a,min(a+n,b+1))
    # Top bar projects its inward end through the space between the bars.
    for c in inward(top):
        for r in range(top[0]+1,bottom[0]): out[r][c]=fill
    # Lower bar's inward segment fills below marker contours, column by column.
    cols=inward(bottom)
    if n < 6:
        for c in cols:
            eligible=[r for r,mc in markers if mc<=c]
            if eligible:
                for rr in range(min(eligible)+1,bottom[0]): out[rr][c]=fill
        for r,c in markers: out[r][c]=4
        return out
    # Multi-marker case: preserve the large background replacement pattern.
    for r,c in markers:
        for rr in range(r+1,bottom[0]):
            for cc in cols:
                if cc>=c: out[rr][cc]=fill
        out[r][c]=4
    return out
